// IEEE 754 双精度运算。
if (typeof Math.exp !== "function" || typeof Float64Array !== "function")
  throw Error("当前环境缺少 Math 或 Float64Array。");
lab.hs = {ready:{prepare:true}, language:"JavaScript"};

if (!lab.hs?.ready?.prepare) throw Error("先运行准备环境。");
// 式（24）：p=5、q=1.25、c=1，初相位为零。
// a：X 方向格距；dt：时间步长；T：终止时间。
const hsCfg = {
  N: 1600, a: 0.005, Xleft: -4,
  dt: 0.003125, T: 0.5,
  xMin: -1, xMax: 1, evaluationPoints: 32001
};
const {N,a,Xleft,dt,T,xMin,xMax,evaluationPoints} = hsCfg;
if (![a,Xleft,dt,T,xMin,xMax].every(Number.isFinite) ||
    !(a>0 && dt>0 && T>=0 && xMax>xMin))
  throw Error("要求有限实数、a>0、dt>0、T≥0、xMax>xMin。");
if (!Number.isInteger(N) || N<20 || N>6400 ||
    !Number.isInteger(evaluationPoints) || evaluationPoints<101 || evaluationPoints>64001)
  throw Error("N 应在 20—6400；评价点数应在 101—64001，均取整数。");
const steps=Math.round(T/dt);
if (Math.abs(steps*dt-T)>1e-12 || steps>3200)
  throw Error("T 须为 dt 的整数倍，且步数≤3200。");
const Xright=Xleft+N*a;
emit({type:"table",columns:["N","a","辅助区间 X","Δt","T","时间步数","评价点数"],
  rows:[[N,a,`[${Xleft}, ${Xright}]`,dt,T,steps,evaluationPoints]]});
Object.assign(lab.hs,{cfg:hsCfg,...hsCfg,steps,Xright,ready:{prepare:true,config:true}});

if (!lab.hs?.ready?.config) throw Error("先运行网格与时间配置。");
const {N,a,Xleft,xMin,xMax}=lab.hs;
// 式（24）：X 到 x 的映射，m=u_xx+2。
function exactX(X,t) {
  const z=Math.tanh((3.75*X-0.6*t)/2), S=1-z*z;
  const zx=1.875*S, zxx=-2*zx*1.875*z;
  const J=1+0.3*zx, Jx=0.3*zxx;
  const u=0.09*S, uX=-0.18*z*zx;
  const uXX=-0.18*(zx*zx+z*zxx);
  // 链式法则：d/dx=(1/J)d/dX，其中 J=dx/dX。
  const uxx=(uXX*J-uX*Jx)/(J*J*J);
  return {x:X-0.5+0.3*z,u,rho:1/J,m:uxx+2,X};
}
// dx/dX>0；反解区间为 [x+0.2,x+0.8]。
function exactPhysical(x,t) {
  let lo=x+0.2, hi=x+0.8;
  for (let k=0;k<60;k++) {
    const mid=(lo+hi)/2;
    if (exactX(mid,t).x<x) lo=mid; else hi=mid;
  }
  const value=exactX((lo+hi)/2,t);
  if (Math.abs(value.x-x)>2e-12)
    throw Error("物理坐标反解未达到容差。");
  return value;
}
// 固定网格与初始动网格共用物理端点。
const initial=Array.from({length:N+1},(_,i)=>exactX(Xleft+i*a,0));
const left=initial[0].x, right=initial[N].x, dx=(right-left)/N;
const fixedX=Float64Array.from({length:N+1},(_,i)=>left+i*dx);
if (xMin<=left || xMax>=right)
  throw Error("评价区间必须位于初始物理端点内部。");
emit({type:"table",columns:["初始物理左端","初始物理右端","FD 的 Δx","峰值 u","谷值 ρ"],
  rows:[[left,right,dx,0.09,0.64]]});
Object.assign(lab.hs,{exactX,exactPhysical,initial,left,right,dx,fixedX,ready:{prepare:true,config:true,reference:true}});

if (!lab.hs?.ready?.reference) throw Error("先运行连续参考解。");
const {N,a,Xleft,left,right,dx,fixedX,initial,exactX,exactPhysical}=lab.hs;
// 可积格式状态：[b_0,...,b_(N-1), d_0,...,d_(N-1), x_0]。
function integrableFields(t,state) {
  const u=new Float64Array(N+1), x=new Float64Array(N+1);
  const rho=new Float64Array(N), rhoX=new Float64Array(N);
  const u0=exactX(Xleft,t).u, x0=state[2*N];
  u[0]=u0; x[0]=x0;
  let sumB=0, sumD=0;
  for (let i=0;i<N;i++) {
    const b=state[i], d=state[N+i];
    if (!Number.isFinite(b) || !Number.isFinite(d) || d<=0)
      throw Error("Integrable 出现非有限状态或非正胞元格距。");
    sumB+=b; sumD+=d; u[i+1]=u0+sumB; x[i+1]=x0+sumD;
    rho[i]=a/d; rhoX[i]=(x[i]+x[i+1])/2;
  }
  return {x,u,rhoX,rho};
}
// 式（25）：b、d 和 x_0 的时间导数。
function integrableRHS(t,state) {
  const {u}=integrableFields(t,state), result=new Float64Array(2*N+1);
  for (let i=0;i<N;i++) {
    const b=state[i], d=state[N+i], C=d*d-a*(a-1);
    result[i]=2*d*(u[i+1]+u[i])+(C*C-b*b)/(2*d)-d/2;
    result[N+i]=-b;
  }
  result[2*N]=-u[0]; return result;
}
// 三对角消元解：u_(i-1)-2u_i+u_(i+1)=dx^2*(m_i-2)。
function recoverU(m,ubLeft,ubRight) {
  const count=N-1, c=new Float64Array(count), d=new Float64Array(count);
  for (let j=0;j<count;j++) {
    const diagonal=-2-(j ? c[j-1] : 0);
    let rhs=dx*dx*(m[j+1]-2);
    if (j===0) rhs-=ubLeft;
    if (j===count-1) rhs-=ubRight;
    c[j]=j<count-1 ? 1/diagonal : 0;
    d[j]=(rhs-(j ? d[j-1] : 0))/diagonal;
  }
  const u=new Float64Array(N+1); u[0]=ubLeft; u[N]=ubRight;
  for (let j=count-1;j>=0;j--) u[j+1]=d[j]-(j<count-1 ? c[j]*u[j+2] : 0);
  return u;
}
// FD 状态为内部 m 与 rho，边界取解析值。
function fdFields(t,state) {
  const l=exactPhysical(left,t), r=exactPhysical(right,t);
  const m=new Float64Array(N+1), rho=new Float64Array(N+1);
  m[0]=l.m; m[N]=r.m; rho[0]=l.rho; rho[N]=r.rho;
  for (let i=1;i<N;i++) {
    m[i]=state[i-1]; rho[i]=state[N-1+i-1];
    if (!Number.isFinite(m[i]) || !Number.isFinite(rho[i]) || rho[i]<=0)
      throw Error("FD 出现非有限状态或非正密度。");
  }
  return {x:fixedX,u:recoverU(m,l.u,r.u),rhoX:fixedX,rho,m};
}
// 式（28）：固定网格上的一阶中心差分。
function fdRHS(t,state) {
  const {m,rho,u}=fdFields(t,state), result=new Float64Array(2*(N-1));
  for (let i=1;i<N;i++) {
    const ux=(u[i+1]-u[i-1])/(2*dx);
    const mx=(m[i+1]-m[i-1])/(2*dx), rx=(rho[i+1]-rho[i-1])/(2*dx);
    result[i-1]=u[i]*mx+2*m[i]*ux+rho[i]*rx;
    result[N-1+i-1]=u[i]*rx+rho[i]*ux;
  }
  return result;
}
// 初始 m=D2(u)+2，与演化使用同一二阶差分模板。
function initialStates() {
  const integrable=new Float64Array(2*N+1), fd=new Float64Array(2*(N-1));
  const u0=Float64Array.from(fixedX,x=>exactPhysical(x,0).u);
  for (let i=0;i<N;i++) {
    integrable[i]=initial[i+1].u-initial[i].u;
    integrable[N+i]=initial[i+1].x-initial[i].x;
  }
  integrable[2*N]=left;
  for (let i=1;i<N;i++) {
    fd[i-1]=(u0[i+1]-2*u0[i]+u0[i-1])/(dx*dx)+2;
    fd[N-1+i-1]=exactPhysical(fixedX[i],0).rho;
  }
  return {integrable,fd};
}
// 物理节点上的分段线性重构。
function interpolate(xs,values,targets) {
  if (targets[0]<xs[0] || targets[targets.length-1]>xs[xs.length-1])
    throw Error("数值网格未覆盖整个评价区间。");
  const out=new Float64Array(targets.length); let j=0;
  for (let k=0;k<targets.length;k++) {
    while (j<xs.length-2 && xs[j+1]<targets[k]) j++;
    const weight=(targets[k]-xs[j])/(xs[j+1]-xs[j]);
    out[k]=values[j]+weight*(values[j+1]-values[j]);
  }
  return out;
}
Object.assign(lab.hs,{integrableFields,integrableRHS,recoverU,fdFields,fdRHS,initialStates,interpolate,ready:{prepare:true,config:true,reference:true,spatial:true}});

if (!lab.hs?.ready?.spatial) throw Error("先运行空间格式。");
// 式（29）：每一级重新恢复场值和解析边界。
function rk4Step(rhs,t,state,delta) {
  const add=(z,k,factor)=>Float64Array.from(z,(value,i)=>value+factor*k[i]);
  const k1=rhs(t,state), k2=rhs(t+delta/2,add(state,k1,delta/2));
  const k3=rhs(t+delta/2,add(state,k2,delta/2)), k4=rhs(t+delta,add(state,k3,delta));
  return Float64Array.from(state,(value,i)=>value+delta*(k1[i]+2*k2[i]+2*k3[i]+k4[i])/6);
}
Object.assign(lab.hs,{rk4Step,ready:{prepare:true,config:true,reference:true,spatial:true,rk4:true}});

if (!lab.hs?.ready?.rk4) throw Error("先运行四阶时间步。");
const {steps,dt,T,initialStates,rk4Step,integrableRHS,fdRHS,integrableFields,fdFields}=lab.hs;
// 时间层：t_n=n*dt，T=steps*dt。
let {integrable,fd}=initialStates();
for (let step=0;step<steps;step++) {
  const t=step*dt;
  integrable=rk4Step(integrableRHS,t,integrable,dt);
  fd=rk4Step(fdRHS,t,fd,dt);
}
const liveFields={Integrable:integrableFields(T,integrable),FD:fdFields(T,fd)};
Object.assign(lab.hs,{integrable,fd,liveFields,ready:{prepare:true,config:true,reference:true,spatial:true,rk4:true,evolve:true}});
emit({type:"table",columns:["方案","已推进步数","当前时间","物理节点数"],
  rows:Object.entries(liveFields).map(([name,f])=>[name,steps,T,f.x.length])});

if (!lab.hs?.ready?.evolve) throw Error("先运行实际演化。");
const {N,a,Xleft,dt,T,steps,xMin,xMax,evaluationPoints,liveFields,exactPhysical,interpolate}=lab.hs;
// 式（30）：公共物理网格上的最大绝对误差。
const xx=Float64Array.from({length:evaluationPoints},(_,i)=>
  xMin+(xMax-xMin)*i/(evaluationPoints-1));
const reference=Array.from(xx,x=>exactPhysical(x,T));
const hsResults={}, resultRows=[];
for (const [name,f] of Object.entries(liveFields)) {
  const u=interpolate(f.x,f.u,xx), rho=interpolate(f.rhoX,f.rho,xx);
  const eu=Float64Array.from(u,(v,i)=>Math.abs(v-reference[i].u));
  const er=Float64Array.from(rho,(v,i)=>Math.abs(v-reference[i].rho));
  let Eu=0, Erho=0, minDx=Infinity, minRho=Infinity;
  for (let i=0;i<evaluationPoints;i++) {Eu=Math.max(Eu,eu[i]);Erho=Math.max(Erho,er[i]);}
  for (let i=1;i<f.x.length;i++) minDx=Math.min(minDx,f.x[i]-f.x[i-1]);
  for (const r of f.rho) minRho=Math.min(minRho,r);
  hsResults[name]={Eu,Erho,eu,er,u,rho,minDx,minRho};
  resultRows.push([name,Eu,Erho,minDx,minRho]);
}
emit({type:"table",columns:["现场运行的方案","E_u(T)","E_ρ(T)","终点最小格距","终点最小密度"],rows:resultRows});
// 每个绘图区间保留其评价点上的最大误差。
const bins=100, centers=Array.from({length:bins},(_,i)=>xMin+(i+0.5)*(xMax-xMin)/bins);
for (const [key,label] of [["eu","u"],["er","ρ"]]) {
  const series=[];
  for (const name of ["Integrable","FD"]) {
    const envelope=new Array(bins).fill(0), values=hsResults[name][key];
    for (let k=0;k<evaluationPoints;k++) {
      const bin=Math.min(bins-1,Math.floor((xx[k]-xMin)/(xMax-xMin)*bins));
      envelope[bin]=Math.max(envelope[bin],values[k]);
    }
    // 对数图显示下限为 1e-16；误差范数不截断。
    series.push({name,x:centers,y:envelope.map(v=>Math.log10(Math.max(v,1e-16)))});
  }
  emit({type:"series",title:`单孤子 ${label} 的分段最大绝对误差`,
    xLabel:"物理坐标 x",yLabel:`log10(max |${label}_h − ${label}|)`,series});
}
// 仅原配置使用原表误差作回归核对。
const isReportDefault=N===1600 && a===0.005 && Xleft===-4 && dt===0.003125 &&
  T===0.5 && xMin===-1 && xMax===1 && evaluationPoints===32001;
if (isReportDefault) {
  const saved={Integrable:[0.010012749796509766,0.0011496748742060303],
    FD:[9.399310918062342e-7,3.046420677166317e-6]};
  let discrepancy=0;
  const auditRows=[];
  for (const name of ["Integrable","FD"]) {
    const r=hsResults[name], target=saved[name];
    const du=Math.abs(r.Eu-target[0]), dr=Math.abs(r.Erho-target[1]);
    discrepancy=Math.max(discrepancy,du,dr);
    auditRows.push([name,target[0],target[1],du,dr]);
  }
  emit({type:"table",columns:["方案","原表 E_u","原表 E_ρ","现场 E_u 与原表之差","现场 E_ρ 与原表之差"],rows:auditRows});
  if (discrepancy>1e-8) throw Error("默认配置与原报告误差不吻合，请检查已编辑的核心代码。");
}
Object.assign(lab.hs,{xx,reference,hsResults,resultRows,ready:{prepare:true,config:true,reference:true,spatial:true,rk4:true,evolve:true,error:true}});
